_SHORT_DURATION = re.compile(r"(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?")
# ISO 8601 durations: PnDTnHnMnS (weeks, years and months are not supported
# because their length in seconds is not fixed).
_ISO_DURATION = re.compile(
    r"P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?", re.IGNORECASE
)


def parse_duration(text):
    """Parse '1h30m' style or ISO 8601 (e.g. 'PT1H30M') durations into seconds."""
    raw = text.strip()
    if raw[:1] in ("P", "p"):
        return _parse_iso_duration(raw, text)
    m = _SHORT_DURATION.fullmatch(raw)
    if not m or not any(m.groups()):
        raise ValueError(f"bad duration: {text}")
    h, mi, s = (int(g or 0) for g in m.groups())
    return h * 3600 + mi * 60 + s


def _parse_iso_duration(raw, original):
    m = _ISO_DURATION.fullmatch(raw)
    # Reject bare "P" and "PT" (no components), and "P1DT" (T with no time part).
    if not m or not any(m.groups()) or raw.upper().endswith("T"):
        raise ValueError(f"bad duration: {original}")
    d, h, mi, s = (int(g or 0) for g in m.groups())
    return d * 86400 + h * 3600 + mi * 60 + s

